let raw = $input.item.json.text || 
          $input.item.json.output || 
          $input.item.json.response || '';

raw = raw.replace(/\\n/g, '\n').replace(/\\"/g, '"');

const titleMatch = raw.match(/"title"\s*:\s*"([^"]+)"/);
const title = titleMatch ? titleMatch[1] : '';

try {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(cleaned);
  return {
    title: title || parsed.title || '',
    linkedin_post: parsed.linkedin_post || '',
    tweet_1: parsed.tweet_1 || '',
    tweet_2: parsed.tweet_2 || '',
    tweet_3: parsed.tweet_3 || '',
    tweet_4: parsed.tweet_4 || '',
    tweet_5: parsed.tweet_5 || '',
    newsletter_snippet: parsed.newsletter_snippet || '',
    instagram_caption: parsed.instagram_caption || ''
  };
} catch(e) {
  return { error: e.message, raw: raw.substring(0, 200) };
}

