let raw = $input.item.json.text || $input.item.json.output || '';

// Clean control characters
raw = raw
  .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, '')
  .replace(/\\n/g, '\n')
  .replace(/\\t/g, ' ')
  .replace(/```json|```/g, '')
  .trim();

try {
  const parsed = JSON.parse(raw);
  const lead = $('Parse Lead Data').item.json;
  return [{ json: { 
    ...lead, 
    subject: parsed.subject || '',
    body: parsed.body || ''
  }}];
} catch(e) {
  // Try extracting with regex if JSON parse fails
  const subjectMatch = raw.match(/"subject"\s*:\s*"([^"]+)"/);
  const bodyMatch = raw.match(/"body"\s*:\s*"([\s\S]+?)"\s*\}/);
