parameters.jsCode:
const appointments = $input.all();
const tomorrow = new Date();
tomorrow.setDate(tomorrow.getDate() + 1);
const tomorrowStr = tomorrow.toISOString().split('T')[0];

const tomorrowAppts = appointments.filter(item => {
  const apptDate = item.json['Date'] || '';
  return apptDate === tomorrowStr;
});

return tomorrowAppts.map(item => ({ json: item.json }));

